import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

delete_groups = {"@9T", "SAL", "T9A"}
kept = []

for r in range(2, 208):
    a = vws.cell(row=r, column=1).value
    if a is not None and str(a).strip() in delete_groups:
        continue

    row = []
    for c in range(1, 5):
        v = vws.cell(row=r, column=c).value
        if isinstance(v, str):
            v = v.strip()
        row.append(v)
    kept.append(row)

for r in range(2, 208):
    for c in range(1, 5):
        ws.cell(row=r, column=c).value = None

for i, row in enumerate(kept[:206]):
    r = 2 + i
    for c, v in enumerate(row, start=1):
        ws.cell(row=r, column=c).value = v

wb.save(OUT)

print("kept_rows:", len(kept))
if kept:
    print("first:", kept[0])
    print("last:", kept[-1])
